#!/usr/bin/env python3
"""Deployment inputs: strict dotenv subset, no shell execution; stdlib only."""
import json
import math
import os
import re
import sys
from pathlib import Path
from urllib.parse import urlparse

ROOT = Path(__file__).resolve().parents[1]


def read_env(path):
    result = {}
    for number, raw in enumerate(Path(path).read_text().splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        key, sep, value = line.partition('=')
        if not sep or not re.fullmatch(r'[A-Z][A-Z0-9_]*', key):
            raise ValueError(f'{path}:{number}: 需要 KEY=value')
        if key in result:
            raise ValueError(f'{path}:{number}: 重复字段 {key}')
        if value.startswith("'") and value.endswith("'"):
            value = value[1:-1]
        if any(c in value for c in '\n\r\x00'):
            raise ValueError(f'{key}: 不允许控制字符')
        result[key] = value
    return result


def load(path):
    defaults = read_env(ROOT / '.env.example')
    supplied = read_env(path)
    unknown = supplied.keys() - defaults.keys()
    if unknown:
        raise ValueError(f'未知配置字段: {sorted(unknown)}')
    return defaults | supplied


def integer(env, key, maximum=2**32 - 1):
    value = env[key]
    if not re.fullmatch(r'[1-9][0-9]*', value) or int(value) > maximum:
        raise ValueError(f'{key}: 需要 1..{maximum} 的整数')
    return int(value)


def validate(env):
    for key in ('AUTHORITY_DOMAIN', 'RELAY_DOMAIN', 'SMTP_HOST'):
        value = env[key]
        if key == 'SMTP_HOST' and not value:
            continue
        labels = value.split('.')
        if len(value) > 253 or len(labels) < 2 or not all(
            re.fullmatch(r'[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?', label)
            for label in labels
        ):
            raise ValueError(f'{key}: 需要小写 DNS 主机名')
    if env['AUTHORITY_DOMAIN'] == env['RELAY_DOMAIN']:
        raise ValueError('权威与 relay 域名必须不同')
    if not re.fullmatch(r'[A-Za-z0-9_.+%-]+@[A-Za-z0-9.-]+', env['ACME_EMAIL']):
        raise ValueError('ACME_EMAIL 格式无效')
    for key in ('AUTHORITY_IMAGE', 'RELAY_IMAGE'):
        if not re.fullmatch(r'[a-zA-Z0-9._/:-]+:[a-zA-Z0-9._-]+@sha256:[0-9a-f]{64}', env[key]):
            raise ValueError(f'BLOCKED: {key} 需要版本标签与 sha256 digest')
    for key in ('AUTHORITY_IMAGE', 'RELAY_IMAGE', 'CADDY_IMAGE', 'GATEWAY_IMAGE'):
        value = env[key]
        if not re.fullmatch(r'[a-zA-Z0-9._/:-]+:[a-zA-Z0-9._-]+(?:@sha256:[0-9a-f]{64})?', value):
            raise ValueError(f'{key}: 镜像必须固定版本')
        if value.split('@')[0].rsplit(':', 1)[1] in ('latest', 'main', 'stable', 'alpine'):
            raise ValueError(f'{key}: 不允许浮动版本')
    for key in ('ACCOUNT_OPEN_SIGNUP', 'SMOKE_SIGNUP', 'BACKUP_PLAINTEXT_ACK',
                'RESTORE_UNPINNED_ACK'):
        if env[key] not in ('0', '1'):
            raise ValueError(f'{key}: 仅允许 0/1')
    if env['RELAY_FALLBACK'] not in ('true', 'false'):
        raise ValueError('RELAY_FALLBACK: 仅允许 true/false')
    limits = {'SMTP_PORT': 65535, 'REVOCATION_POLL_SECS': 3600,
              'REVOCATION_MAX_AGE_SECS': 86400, 'NEW_DEVICE_WINDOW_HOURS': 720,
              'APPROVAL_TIMEOUT_SECS': 3600, 'SMOKE_TIMEOUT_SECS': 120,
              'LOG_MAX_FILES': 100, 'RESTORE_VERIFY_TIMEOUT_SECS': 300}
    for key in ('AUTH_REQUESTS_PER_10S', 'RELAY_ACCEPT_PER_SEC', 'RELAY_ACCEPT_BURST',
                'RELAY_RX_BYTES_PER_SEC', 'RELAY_RX_BURST_BYTES'):
        limits[key] = 2**32 - 1
    for key, limit in limits.items():
        integer(env, key, limit)
    for service in ('AUTHORITY', 'RELAY', 'CADDY', 'GATEWAY'):
        if not re.fullmatch(r'[1-9][0-9]*[mg]', env[service + '_MEMORY']):
            raise ValueError(f'{service}_MEMORY: 需要正整数 m/g')
        cpu = float(env[service + '_CPUS'])
        if not math.isfinite(cpu) or not 0 < cpu <= 64:
            raise ValueError(f'{service}_CPUS: 需要 (0,64] 数字')
    if not re.fullmatch(r'[1-9][0-9]*m', env['LOG_MAX_SIZE']):
        raise ValueError('LOG_MAX_SIZE: 需要正整数 m')
    if not env['BACKUP_DIR'].strip():
        raise ValueError('BACKUP_DIR 不能为空')
    if env['BACKUP_ENCRYPT'] not in ('', 'age', 'gpg'):
        raise ValueError('BACKUP_ENCRYPT: 仅允许 age/gpg/空值')
    recipient = env['BACKUP_RECIPIENT']
    if recipient and (recipient.startswith('-') or any(c.isspace() for c in recipient)):
        raise ValueError('BACKUP_RECIPIENT: 需要单个公钥/指纹，不允许选项或空白')
    if env['BACKUP_IDENTITY'] and not Path(env['BACKUP_IDENTITY']).is_absolute():
        raise ValueError('BACKUP_IDENTITY: 需要绝对文件路径')
    smtp = [env[k] for k in ('SMTP_HOST', 'SMTP_USER', 'SMTP_PASS', 'SMTP_FROM')]
    if any(smtp) and not all(smtp):
        raise ValueError('SMTP_HOST/USER/PASS/FROM 必须全部填写或全部留空')
    if bool(env['SMOKE_USERNAME']) != bool(env['SMOKE_PASSWORD']):
        raise ValueError('自检账号与密码必须同时提供')
    if env['SMOKE_SIGNUP'] == '1' and not env['SMOKE_USERNAME']:
        raise ValueError('SMOKE_SIGNUP=1 需要测试账号')
    fp = env['EXPECTED_FINGERPRINT']
    if fp and not re.fullmatch(r'[0-9a-f]{64}', fp):
        raise ValueError('EXPECTED_FINGERPRINT 必须为完整小写 SHA-256，不能为 kid')
    for url in relay_urls(env):
        parsed = urlparse(url)
        if (parsed.scheme != 'https' or not parsed.hostname or parsed.username or
                parsed.password or parsed.query or parsed.fragment or parsed.path not in ('', '/')):
            raise ValueError('RELAY_URLS 需要逗号分隔的 HTTPS 源站 URL')
        _ = parsed.port


def relay_urls(env):
    return [v.strip() for v in env['RELAY_URLS'].split(',') if v.strip()] or [
        'https://' + env['RELAY_DOMAIN']]


def interconnect(env, client=False):
    return {
        'authority': {'url': 'https://' + env['AUTHORITY_DOMAIN'] if client else None,
                      'publicKeyFingerprints': [env['EXPECTED_FINGERPRINT']] if client else []},
        'relay': {'urls': relay_urls(env), 'fallback': env['RELAY_FALLBACK'] == 'true'},
        'security': {'revocationPollSecs': int(env['REVOCATION_POLL_SECS']),
                     'revocationMaxAgeSecs': int(env['REVOCATION_MAX_AGE_SECS']),
                     'newDeviceWindowHours': int(env['NEW_DEVICE_WINDOW_HOURS']),
                     'approvalTimeoutSecs': int(env['APPROVAL_TIMEOUT_SECS'])},
    }


def prepare(env):
    validate(env)
    out = ROOT / '.generated'
    out.mkdir(mode=0o700, exist_ok=True)
    for name in ('Caddyfile', 'haproxy.cfg', 'relay.toml'):
        content = (ROOT / 'templates' / name).read_text()
        for key in re.findall(r'@([A-Z_0-9]+)@', content):
            content = content.replace('@' + key + '@', env[key])
        (out / name).write_text(content)
        (out / name).chmod(0o644)
    (out / 'authority.json').write_text(json.dumps(interconnect(env), indent=2) + '\n')
    (out / 'authority.json').chmod(0o644)
    # Compose 单引号值保持 $ 为字面量，不让 SMTP 密码进入变量插值。
    content = ''.join(k + "='" + v.replace("'", "\\'") + "'\n" for k, v in env.items())
    target = out / 'compose.env'
    target.touch(mode=0o600, exist_ok=True)
    target.chmod(0o600)
    target.write_text(content)
    client = out / 'client-interconnect.json'
    if env['EXPECTED_FINGERPRINT']:
        client.write_text(json.dumps(interconnect(env, True), indent=2) + '\n')
    else:
        client.unlink(missing_ok=True)


def main():
    action, path, *args = sys.argv[1:]
    env = load(path)
    if action == 'prepare':
        prepare(env)
    elif action == 'compose':
        validate(env)
        command = ['docker', 'compose', '--project-directory', str(ROOT),
                   '--env-file', str(ROOT / '.generated/compose.env'),
                   '-f', str(ROOT / 'docker-compose.yml'), *args]
        # Explicit task inputs override ambient shell variables, including project identity.
        os.execvpe('docker', command, os.environ | env | {'COMPOSE_PROJECT_NAME': 'polaris-singapore'})
    elif action == 'value':
        print(env[args[0]])
    else:
        raise ValueError('未知动作')


if __name__ == '__main__':
    try:
        main()
    except (OSError, ValueError, KeyError) as error:
        sys.exit(str(error))
#!/usr/bin/env python3
"""Stopped-authority snapshots: normalize SQLite WAL, strictly validate before restore."""
import base64
import hashlib
import json
import os
import shutil
import sqlite3
import subprocess
import sys
import tarfile
from contextlib import closing
from datetime import datetime, timezone
from pathlib import Path

from backup_crypto import clean, decrypt, encrypt, policy, workspace
from config import load, validate

PAYLOAD = ('collab.db', 'account_authority.key')
MEMBERS = {*PAYLOAD, 'manifest.json'}


def key_check(data):
    raw = data.strip()
    seed = base64.b64decode(raw + b'=' * (-len(raw) % 4), altchars=b'-_', validate=True)
    if len(seed) != 32:
        raise ValueError('签名私钥必须是 32 字节种子')


def check_db(path):
    with closing(sqlite3.connect(path.as_uri() + '?mode=ro', uri=True)) as db:
        if db.execute('PRAGMA integrity_check').fetchall() != [('ok',)]:
            raise ValueError('SQLite 完整性检查失败')
        if not db.execute("SELECT 1 FROM sqlite_master WHERE type='table'").fetchone():
            raise ValueError('拒绝备份/恢复空数据库')


def pack(source, destination, image, env):
    mode = policy(env)
    source, destination = Path(source).resolve(), Path(destination).resolve()
    for name in PAYLOAD:
        if (source / name).is_symlink() or not (source / name).is_file():
            raise ValueError(f'缺失或不安全的备份文件: {name}')
    key_check((source / PAYLOAD[1]).read_bytes())
    with workspace() as folder:
        normalized = Path(folder)
        # source 是停止后复制的目录；普通读写打开以正确恢复 WAL，不使用 immutable=1。
        with closing(sqlite3.connect(source / 'collab.db')) as src:
            with closing(sqlite3.connect(normalized / 'collab.db')) as dst:
                src.backup(dst)
        check_db(normalized / 'collab.db')
        (normalized / PAYLOAD[1]).write_bytes((source / PAYLOAD[1]).read_bytes())
        manifest = {'format': 1, 'authorityImage': image, 'sha256': {}}
        for name in PAYLOAD:
            manifest['sha256'][name] = hashlib.sha256((normalized / name).read_bytes()).hexdigest()
        (normalized / 'manifest.json').write_text(json.dumps(manifest, indent=2))
        stamp = datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
        target = destination / ('authority-' + stamp + '.tar')
        if mode:
            target = target.with_suffix('.tar.' + mode)
        partial = target.with_name(target.name + '.partial')
        plaintext = normalized / 'snapshot.tar'
        try:
            with tarfile.open(plaintext, 'x') as archive:
                for name in sorted(MEMBERS):
                    info = archive.gettarinfo(str(normalized / name), arcname=name)
                    info.uid = info.gid = 1000
                    info.uname = info.gname = ''
                    info.mode = 0o600
                    with (normalized / name).open('rb') as body:
                        archive.addfile(info, body)
            verify(plaintext)
            if mode:
                encrypt(plaintext, partial, mode, env['BACKUP_RECIPIENT'])
            else:
                with plaintext.open('rb') as body, partial.open('xb') as output:
                    shutil.copyfileobj(body, output)
            partial.rename(target)
        except BaseException:
            partial.unlink(missing_ok=True)
            raise
        print(target)


def verify(path):
    with tarfile.open(path, 'r:') as archive:
        members = archive.getmembers()
        if len(members) != len(MEMBERS) or {m.name for m in members} != MEMBERS:
            raise ValueError('备份成员不匹配，拒绝路径穿越/重复文件/额外文件')
        if any(not m.isfile() or m.issym() or m.islnk() for m in members):
            raise ValueError('备份只允许普通文件')
        meta = archive.extractfile('manifest.json')
        if meta is None or archive.getmember('manifest.json').size > 16384:
            raise ValueError('非法 manifest')
        manifest = json.load(meta)
        if manifest.get('format') != 1 or set(manifest.get('sha256', {})) != set(PAYLOAD):
            raise ValueError('不支持的备份格式')
        with workspace() as folder:
            for name in PAYLOAD:
                digest = hashlib.sha256()
                target = Path(folder) / name
                with target.open('wb') as output, archive.extractfile(name) as body:
                    while chunk := body.read(1024 * 1024):
                        digest.update(chunk)
                        output.write(chunk)
                if digest.hexdigest() != manifest['sha256'][name]:
                    raise ValueError(f'校验和不匹配: {name}')
            key_check((Path(folder) / PAYLOAD[1]).read_bytes())
            check_db(Path(folder) / 'collab.db')
    return manifest


def unpack(source, destination, env):
    if Path(source).suffix == '.tar':
        # Historic plaintext archives remain readable; new backups require policy().
        verify(source)
        return str(source)
    target = Path(destination) / 'snapshot.tar'
    decrypt(source, target, env)
    verify(target)
    return str(target)


def settings(path):
    env = load(path)
    validate(env)
    return env


if __name__ == '__main__':
    os.umask(0o077)
    try:
        if sys.argv[1] == 'pack':
            pack(*sys.argv[2:5], settings(sys.argv[5]))
        elif sys.argv[1] == 'policy':
            policy(settings(sys.argv[2]))
        elif sys.argv[1] == 'unpack':
            print(unpack(*sys.argv[2:4], settings(sys.argv[4])))
        elif sys.argv[1] == 'clean':
            clean(sys.argv[2])
        elif sys.argv[1] == 'verify':
            verify(sys.argv[2])
            print('备份格式、校验和、SQLite、私钥种子格式：PASS')
        else:
            raise ValueError('未知动作')
    except (OSError, ValueError, sqlite3.Error, tarfile.TarError, subprocess.CalledProcessError) as error:
        sys.exit(str(error))
